contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs: optionally deposit some ether, then attempt CashOut(amount)
    // params: depositAmt to send to Deposit (must be >0 to have effect because C uses MinDeposit = 1 ether),
    // cashOutAmt is the attempted withdrawal amount.
    function run(uint depositAmt, uint cashOutAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // Record balance view for this contract in C before actions
        uint beforePersonBalance = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // If depositAmt > 0 we try to call Deposit with value depositAmt
        if (depositAmt > 0) {
            // call Deposit paying depositAmt
            c.Deposit{value: depositAmt}();
        }

        // Record after deposit state
        uint afterDepositPersonBalance = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // Now attempt CashOut(cashOutAmt) and capture whether it reverted
        bool reverted;
        try c.CashOut(cashOutAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final observable state
        uint finalPersonBalance = c.balances(address(this));
        uint finalContractEth = address(c).balance;

        // General property asserted:
        // 1) The contract's recorded balance for this test contract never increases as a result of CashOut call:
        //    finalPersonBalance <= afterDepositPersonBalance
        // 2) If CashOut succeeded (not reverted) then the contract's ETH balance decreased by exactly the same amount
        //    that the recorded balance decreased; if it reverted then recorded balance is unchanged and contract ETH unchanged.
        assert(
            // (A) recorded balance did not increase due to CashOut
            (finalPersonBalance <= afterDepositPersonBalance)
            &&
            // (B) either CashOut reverted and nothing changed, or it succeeded and both contract eth and recorded balance decreased equally
            (reverted
                ? (finalPersonBalance == afterDepositPersonBalance && finalContractEth == afterDepositContractEth)
                : (
                    // when succeeded, recorded balance decreased by some d <= afterDepositPersonBalance
                    (afterDepositPersonBalance >= finalPersonBalance)
                    // contract ETH decreased by exactly the same delta
                    && (afterDepositContractEth - finalContractEth == (afterDepositPersonBalance - finalPersonBalance))
                )
            )
        );
    }

    // receive to accept ETH when c sends Ether during CashOut
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // test: depositAmt is the Ether sent to c.Deposit
    function run(uint depositAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // observe before-state
        uint beforeRecorded = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // perform Deposit as a top-level state-changing call
        bool didRevert;
        try c.Deposit{value: depositAmt}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // observe after-state
        uint afterRecorded = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // General rule:
        // - If depositAmt > c.MinDeposit() then Deposit must NOT revert, and both the recorded balance
        //   and the contract's ETH balance increase by exactly depositAmt.
        // - If depositAmt <= c.MinDeposit() then Deposit makes no state change (recorded and contract balances equal before), and must NOT revert.
        // (The contract's implementation uses a conditional and does not revert on small deposits.)
        uint minDep = c.MinDeposit();

        assert(
            (depositAmt > minDep
                ? (
                    // succeeded
                    didRevert == false
                    && afterRecorded == beforeRecorded + depositAmt
                    && afterContractEth == beforeContractEth + depositAmt
                )
                : (
                    // depositAmt <= minDep: Deposit is ignored and should not revert and no balances change
                    didRevert == false
                    && afterRecorded == beforeRecorded
                    && afterContractEth == beforeContractEth
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
