    // single public test: attempt a CashOut of 'amt'
    function run(uint amt) public payable {
        // no extra preconditions on amt; ensure this test contract can receive Ether refunds
        // Observe before-state
        uint beforeRecorded = c.balances(address(this));
        uint beforeThisBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        // Try to call CashOut(amt) — must be a top-level state-changing call
        bool didRevert;
        try c.CashOut(amt) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observe after-state
        uint afterRecorded = c.balances(address(this));
        uint afterThisBal = address(this).balance;
        uint afterCbal = address(c).balance;

        // General rule:
        // - If call succeeded (didRevert == false) then recorded balance decreased by amt
        //   and this contract's balance increased by exactly amt and c's balance decreased by exactly amt.
        // - If call reverted (didRevert == true) then recorded balance and all balances unchanged.
        assert(
            didRevert
            ? (
                afterRecorded == beforeRecorded
                && afterThisBal == beforeThisBal
                && afterCbal == beforeCbal
              )
            : (
                afterRecorded + amt == beforeRecorded
                && afterThisBal == beforeThisBal + amt
                && afterCbal + amt == beforeCbal
              )
        );
    }

    receive() external payable {}
}

