contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries a CashOut of amount 'am'. It may optionally first deposit 'dep' to ensure some balance.
    // We take dep as a parameter and send it as ETH to Deposit. The function is payable so the test harness
    // can fund this contract for the deposit.
    function run(uint dep, uint am) public payable {
        // ensure this contract has enough ETH to call Deposit with 'dep'
        require(address(this).balance >= dep, "insufficient balance for deposit");

        // read before values
        uint beforeLedger = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // attempt Deposit (state-changing call must be top-level)
        bool depositReverted;
        try c.Deposit{value: dep}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // read ledger after deposit attempt to know current recorded balance
        uint afterDepositLedger = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // attempt CashOut of amount 'am'
        bool cashoutReverted;
        try c.CashOut(am) {
            cashoutReverted = false;
        } catch {
            cashoutReverted = true;
        }

        // read final observables
        uint finalLedger = c.balances(address(this));
        uint finalContractEth = address(c).balance;

        // Determine the recorded balance that applied to the CashOut call: that's afterDepositLedger.
        // If CashOut did not revert and am <= afterDepositLedger then ledger decreased by am and contract ETH decreased by am.
        // Otherwise ledger and contract ETH remain equal to their values before CashOut (i.e., afterDeposit values).
        assert(
            (
                (!cashoutReverted && am <= afterDepositLedger) &&
                finalLedger == (afterDepositLedger - am) &&
                finalContractEth == (afterDepositContractEth - am)
            ) || (
                (cashoutReverted || am > afterDepositLedger) &&
                finalLedger == afterDepositLedger &&
                finalContractEth == afterDepositContractEth
            )
        );
    }

    // accept ETH forwarded from c during CashOut
    receive() external payable {}
}

